#include <stdio.h>
#include <stdlib.h>

// Define the structure for an edge in the graph
typedef struct {
    int vertex1;
    int vertex2;
    int weight;
} Edge;

// Define the structure for a disjoint set
typedef struct {
    int *parent;
    int size;
} DisjointSet;

// Function to find the parent of a vertex in the disjoint set
int find(DisjointSet *ds, int vertex) {
    if (ds->parent[vertex] == vertex) {
        return vertex;
    }
    return find(ds, ds->parent[vertex]);
}

// Function to union two vertices in the disjoint set
void unionVertices(DisjointSet *ds, int vertex1, int vertex2) {
    int parent1 = find(ds, vertex1);
    int parent2 = find(ds, vertex2);
    if (parent1 != parent2) {
        ds->parent[parent1] = parent2;
    }
}

// Function to calculate the minimum spanning tree using Kruskal's algorithm
void kruskal(Edge *edges, int numEdges, int numVertices) {
    DisjointSet ds;
    ds.parent = (int *)malloc(numVertices * sizeof(int));
    ds.size = numVertices;
    for (int i = 0; i < numVertices; i++) {
        ds.parent[i] = i;
    }
    int numEdgesInMST = 0;
    int totalWeight = 0;
    printf("weight=%d edges=", totalWeight);
    for (int i = 0; i < numEdges; i++) {
        int vertex1 = edges[i].vertex1;
        int vertex2 = edges[i].vertex2;
        int weight = edges[i].weight;
        if (find(&ds, vertex1) != find(&ds, vertex2)) {
            unionVertices(&ds, vertex1, vertex2);
            totalWeight += weight;
            numEdgesInMST++;
            printf("%d-%d", vertex1, vertex2);
            if (numEdgesInMST < numVertices - 1) {
                printf(",");
            }
        }
    }
    printf("\n");
    free(ds.parent);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s <number_of_vertices>\n", argv[0]);
        return 1;
    }
    int numVertices = atoi(argv[1]);
    int numEdges = (numVertices * (numVertices - 1)) / 2;
    Edge *edges = (Edge *)malloc(numEdges * sizeof(Edge));
    for (int i = 0; i < numEdges; i++) {
        edges[i].vertex1 = i / (numVertices - 1);
        edges[i].vertex2 = i % (numVertices - 1) + 1;
        edges[i].weight = rand() % 100 + 1;
    }
    kruskal(edges, numEdges, numVertices);
    free(edges);
    return 0;
}
